const MiddlewareManager = require ('../MiddlewareManager');
const TaleManager = require ('../TaleManager');

class Ponytail {
  constructor (params) {
    const {configuration} = params;
    this.TaleManager = TaleManager;
    this.configuration = configuration || {};

    this.MiddlewareManager = new MiddlewareManager ({configuration});

    initialiseMethods ({
      MiddlewareManager: this.MiddlewareManager,
      instance: this,
      configuration,
    });
  }
}

function initialiseMethods({instance, configuration, MiddlewareManager}) {
  // here we wrap every method with middleware
  // and later on attach to Ponytail instance
  const methods = require ('./methods');
  Object.keys (methods).forEach (methodName => {
    const method = methods[methodName].bind (instance);
    instance[methodName] = MiddlewareManager.wrapWithMiddleware ({
      method,
      methodName,
    });
  });
}

module.exports = new Ponytail ({});
